<script lang="ts">
	import { Api } from '$lib/api';
	import type { AppSettings, EngineDetail, EngineSpeaker, GenerationTask, GeneratePlanResponse, GenerateRequest, LongformTask, PlannedTextSegment, PresetTemplate, TTSVerificationResponse, VoiceAsset } from '$lib/api/types';
	import { taskStatusLabel } from '$lib/labels';
	import { CheckSquare, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, Download, FileText, Hash, Info, Mic, Cpu, Pencil, Pause, Play, Plus, Repeat, RotateCcw, Save, Scissors, Search, Send, Settings, SlidersHorizontal, Square, Trash2, Wand2, X } from 'lucide-svelte';
	import { onMount, untrack } from 'svelte';
	import EngineSelector from './components/EngineSelector.svelte';
	import VoiceSelector from './components/VoiceSelector.svelte';
	import TextInput from './components/TextInput.svelte';
	import ParameterPanel from './components/ParameterPanel.svelte';
	import PlaybackControls from './components/PlaybackControls.svelte';
	import { generateStore } from '$lib/stores/generate';
	import * as H from './helpers';
	import type { LongformStrategy, PresetDraft } from '$lib/stores/generate';
import type { TaskDateFilter, TaskSortBy, TaskSourceFilter, TaskStatusTab } from './helpers';

	const store = generateStore;
	let _autoResizeRO: ResizeObserver | undefined = $state();

	const selected = $derived($store.engines.find(e => e.manifest.engine_id === $store.engineId));
	const activeParamKeys = $derived(new Set(selected?.manifest.parameter_schema.map(p => p.key) ?? []));
	const ttsEngines = $derived($store.engines.filter(e => !e.manifest.capabilities.includes('speech_recognition')));
	const selectedVoice = $derived($store.voices.find(v => v.voice_id === $store.voiceId) ?? null);
	const selectedVoicePreviewUrl = $derived(selectedVoice?.reference_audio_ids[0] ? `/api/voices/${selectedVoice.voice_id}/audio/${selectedVoice.reference_audio_ids[0]}` : '');
	const voiceMap = $derived(new Map($store.voices.map(v => [v.voice_id, v])));
	const engineMap = $derived(new Map($store.engines.map(e => [e.manifest.engine_id, e])));
	const supportsEmotion = $derived(activeParamKeys.has('emotion'));
	const isIndexTTS = $derived($store.engineId === 'indextts-v2'); const isOmniVoice = $derived($store.engineId === 'omnivoice');
	const isMimoPreset = $derived($store.engineId === 'mimo-v2.5-tts-preset'); const isMimoDesign = $derived($store.engineId === 'mimo-v2.5-tts-voicedesign');
	const isMimoClone = $derived($store.engineId === 'mimo-v2.5-tts-voiceclone'); const isMimo = $derived($store.engineId.startsWith('mimo-v2.5'));
	const isEmotiVoice = $derived($store.engineId === 'emotivoice'); const isF5 = $derived($store.engineId === 'f5-tts');
	const isCosyVoice = $derived($store.engineId === 'cosyvoice-sft'); const isCosyVoiceZeroShot = $derived($store.engineId === 'cosyvoice-zero-shot');
	const usesReferenceVoice = $derived(isIndexTTS || isOmniVoice || isMimoClone || isF5 || isCosyVoiceZeroShot);
	const followsReferenceEmotion = $derived(isIndexTTS && !$store.emotion);
	const enginePresets = $derived($store.presets.filter(p => p.engine_id === $store.engineId));
	const hasRunningTasks = $derived($store.tasks.some(t => H.taskIsActive(t) || taskVerificationPending(t)) || $store.longformTasks.some(t => H.statusIsActive(t.status)));
	const visibleLongformTasks = $derived($store.longformTasks.filter(t => t.status !== 'success'));
	const queueOrderedTasks = $derived.by(() => $store.tasks.filter(t => H.taskIsActive(t)).sort((a, b) => a.created_at.localeCompare(b.created_at) || a.task_id.localeCompare(b.task_id)));
	const queueCounts = $derived.by(() => ({ processing: $store.tasks.filter(t => H.taskIsProcessing(t)).length, waiting: $store.tasks.filter(t => H.taskIsWaiting(t)).length }));
	const taskEngineOptions = $derived(['all', ...new Set($store.tasks.map(t => t.engine_id))]);
	const speakerChoices = $derived(isEmotiVoice && $store.speakerCatalog.length ? $store.speakerCatalog.map(s => ({ label: s.label, value: s.speaker_id })) : selected?.manifest.parameter_schema.find(p => p.key === 'speaker_id')?.options ?? []);
	const promptOptions = $derived(selected?.manifest.parameter_schema.find(p => p.key === 'prompt')?.options ?? []);
	const mimoVoiceOptions = $derived(selected?.manifest.parameter_schema.find(p => p.key === 'mimo_voice')?.options ?? []);
	const filteredTasks = $derived.by(() => { const q = $store.taskQuery.trim().toLowerCase(); const now = Date.now(); let f = $store.tasks.filter(t => { if ($store.taskStatusTab === 'active' && !H.taskIsActive(t)) return false; if ($store.taskStatusTab === 'success' && !H.taskIsSuccess(t)) return false; if ($store.taskStatusTab === 'failed' && !H.taskIsFailed(t)) return false; if ($store.taskEngineFilter !== 'all' && t.engine_id !== $store.taskEngineFilter) return false; if ($store.taskSourceFilter !== 'all' && H.engineKind(t.engine_id, engineMap) !== $store.taskSourceFilter) return false; if ($store.taskDateFilter !== 'all') { const ct = new Date(t.created_at).getTime(); if (!Number.isFinite(ct)) return false; const cutoff = $store.taskDateFilter === 'today' ? 86400000 : $store.taskDateFilter === '7d' ? 604800000 : 2592000000; if (now - ct > cutoff) return false; } if (!q) return true; const vn = H.voiceName(t, voiceMap); return H.displayTitle(t).toLowerCase().includes(q) || t.engine_id.toLowerCase().includes(q) || vn.toLowerCase().includes(q) || taskStatusLabel(t.status).toLowerCase().includes(q); }); return f.sort((a, b) => { const ar = (t: GenerationTask) => H.taskIsProcessing(t) ? 0 : H.taskIsWaiting(t) ? 1 : 2; const d = ar(a) - ar(b); if (d !== 0) return d; if (H.taskIsActive(a) && H.taskIsActive(b)) return a.created_at.localeCompare(b.created_at) || a.task_id.localeCompare(b.task_id); if ($store.taskSortBy === 'latest' || $store.taskSortBy === 'oldest') { const ld = H.compareLongformGroupOrder(a, b, f, $store.taskSortBy); if (ld !== null) return ld; } if ($store.taskSortBy === 'oldest') return a.created_at.localeCompare(b.created_at); if ($store.taskSortBy === 'duration_desc') return (b.result_duration_ms ?? 0) - (a.result_duration_ms ?? 0); return b.created_at.localeCompare(a.created_at); }); });
	const pageCount = $derived(Math.max(1, Math.ceil(filteredTasks.length / $store.pageSize)));
	const pagedTasks = $derived.by(() => filteredTasks.slice(($store.currentPage - 1) * $store.pageSize, $store.currentPage * $store.pageSize));
	const visibleSelectableTasks = $derived(pagedTasks.filter(t => H.taskCanDelete(t)));
	const allVisibleSelected = $derived(visibleSelectableTasks.length > 0 && visibleSelectableTasks.every(t => $store.selectedTaskIds.includes(t.task_id)));
	const statusCounts = $derived.by(() => ({ all: $store.tasks.length, active: $store.tasks.filter(t => H.taskIsActive(t)).length, success: $store.tasks.filter(t => H.taskIsSuccess(t)).length, failed: $store.tasks.filter(t => H.taskIsFailed(t)).length }));
	const hasActiveFilters = $derived(Boolean($store.taskQuery.trim()) || $store.taskStatusTab !== 'all' || $store.taskEngineFilter !== 'all' || $store.taskSourceFilter !== 'all' || $store.taskDateFilter !== 'all' || $store.taskSortBy !== 'latest');

	function requestBody(): GenerateRequest { return store.toRequest(); }
	function restoreRequest(req: GenerateRequest) { store.fromRequest(req); }
	function currentPresetParameters() { const req = store.toRequest(); const params: Record<string, unknown> = { language: req.language, output_format: req.output_format }; for (const k of selected?.manifest.parameter_schema.map(p => p.key) ?? []) { const v = (req as unknown as Record<string, unknown>)[k]; if (v !== undefined && v !== null && v !== '') params[k] = v; } return params; }
	function resetPresetDraft() { $store.presetDraft = { name: '', scene: '', description: '', tags: '', sample_text: $store.text }; $store.editingPresetId = ''; }
	function openPresetEditor(p?: PresetTemplate) { if (p) { $store.editingPresetId = p.preset_id; $store.presetDraft = { name: p.name, scene: p.scene, description: p.description, tags: p.tags.join('，'), sample_text: p.sample_text }; } else resetPresetDraft(); $store.showPresetEditor = true; }
	function applyPreset(p: PresetTemplate) { const pp = p.parameters; const m = p.engine_id.startsWith('mimo-v2.5'); store.fromRequest({ text: p.sample_text, engine_id: p.engine_id, voice_id: null, reference_audio_path: null, ref_text: null, language: String(pp.language ?? 'zh'), emotion_mode: pp.emotion ? 'emotion_vector' : 'follow_reference', emotion: typeof pp.emotion === 'string' ? pp.emotion : null, emotion_values: null, emotion_text: typeof pp.emotion_text === 'string' ? pp.emotion_text : null, style_instruction: typeof pp.style_instruction === 'string' ? pp.style_instruction : null, voice_design_prompt: typeof pp.voice_design_prompt === 'string' ? pp.voice_design_prompt : null, mimo_voice: typeof pp.mimo_voice === 'string' ? pp.mimo_voice : null, speaker_id: typeof pp.speaker_id === 'string' ? pp.speaker_id : null, prompt: typeof pp.prompt === 'string' ? pp.prompt : null, nfe_step: Number(pp.nfe_step ?? 32), cfg_strength: Number(pp.cfg_strength ?? 2.0), target_rms: Number(pp.target_rms ?? 0.1), cross_fade_duration: Number(pp.cross_fade_duration ?? 0.15), remove_silence: Boolean(pp.remove_silence ?? false), emo_alpha: Number(pp.emo_alpha ?? 0.6), speed: Number(pp.speed ?? 1.0), temperature: Number(pp.temperature ?? (m ? 0.6 : 0.8)), top_p: Number(pp.top_p ?? (m ? 0.95 : 0.8)), top_k: Number(pp.top_k ?? 30), repetition_penalty: Number(pp.repetition_penalty ?? 10), seed: null, max_mel_tokens: Number(pp.max_mel_tokens ?? 1500), max_text_tokens_per_segment: Number(pp.max_text_tokens_per_segment ?? 120), interval_silence: Number(pp.interval_silence ?? 200), diffusion_steps: Number(pp.diffusion_steps ?? 25), cfg_rate: Number(pp.cfg_rate ?? 0.7), output_format: (pp.output_format ?? 'wav') as 'wav' | 'mp3' | 'flac', } as GenerateRequest); }
	async function savePreset() { if (!$store.presetDraft.name.trim()) return; $store.presetBusy = true; try { const payload = { preset_id: $store.editingPresetId || null, name: $store.presetDraft.name.trim(), scene: $store.presetDraft.scene.trim(), description: $store.presetDraft.description.trim(), engine_id: $store.engineId, sample_text: $store.presetDraft.sample_text.trim() || $store.text, parameters: currentPresetParameters(), source_test_id: null, recommended_voice_type: isOmniVoice && !$store.voiceId ? 'voice_design' : 'reference_voice', tags: $store.presetDraft.tags.split(/[，,]/).map(t => t.trim()).filter(Boolean) }; const saved = $store.editingPresetId ? await Api.updatePreset($store.editingPresetId, payload) : await Api.createPreset(payload); $store.presets = [saved, ...$store.presets.filter(i => i.preset_id !== saved.preset_id)]; $store.showPresetEditor = false; resetPresetDraft(); } catch (e) { $store.error = (e as Error).message; } finally { $store.presetBusy = false; } }
	async function deletePreset(p: PresetTemplate) { if (!p.preset_id.startsWith('custom_')) return; if (!window.confirm(`删除自定义预设「${p.name}」吗？`)) return; $store.presetBusy = true; try { await Api.deletePreset(p.preset_id); $store.presets = $store.presets.filter(i => i.preset_id !== p.preset_id); } catch (e) { $store.error = (e as Error).message; } finally { $store.presetBusy = false; } }
	async function previewSelectedVoice() { if (!$store.voicePreviewAudio || !selectedVoicePreviewUrl) return; if ($store.voicePreviewPlaying) { $store.voicePreviewAudio.pause(); $store.voicePreviewPlaying = false; } else { $store.voicePreviewAudio.currentTime = 0; $store.voicePreviewAudio.play(); $store.voicePreviewPlaying = true; } }
	function upsertTask(t: GenerationTask) { $store.tasks = [t, ...$store.tasks.filter(i => i.task_id !== t.task_id)]; }
	async function poll(taskId: string) { for (let i = 0; i < 900; i++) { const t = await Api.task(taskId); upsertTask(t); if (['success', 'failed', 'cancelled'].includes(t.status)) return; await new Promise(r => setTimeout(r, 1000)); } }
	async function refreshPageData() { const [e, v, t, lf, p, st] = await Promise.all([Api.engines(), Api.voices(), Api.tasks(), Api.longformTasks(), Api.presets(), Api.settings()]); $store.engines = e; $store.voices = v; $store.tasks = t; $store.longformTasks = lf; $store.presets = p; $store.settings = st; const params = new URLSearchParams(location.search); const vId = params.get('voice'); if (!$store.initialized) { const def = e.find(en => en.manifest.engine_id === st.default_engine_id && !en.manifest.capabilities.includes('speech_recognition')); $store.engineId = def?.manifest.engine_id || $store.engineId; $store.voiceId = vId || st.default_voice_id || ''; $store.language = st.default_language || $store.language; $store.showSplitPreview = params.get('tools') === 'text'; $store.initialized = true; } else if (vId) $store.voiceId = vId; }
	async function loadSpeakerCatalog(engine: string, query: string, gender: 'all' | 'F' | 'M') { if (engine !== 'emotivoice') { $store.speakerCatalog = []; return; } const key = `${engine}|${query}|${gender}`; $store.speakerCatalogKey = key; $store.speakerCatalogLoading = true; try { const items = await Api.engineSpeakers(engine, { q: query, gender, limit: query ? 120 : 40 }); if ($store.speakerCatalogKey !== key) return; $store.speakerCatalog = items; if (!$store.speakerId && items[0]) $store.speakerId = items[0].speaker_id; } finally { if ($store.speakerCatalogKey === key) $store.speakerCatalogLoading = false; } }
	function prepareLongformPlan(plan: GeneratePlanResponse) { $store.lastGeneratePlan = plan; $store.textSegments = plan.segments.map(s => s.text); $store.showSplitPreview = plan.segments.length > 1; $store.splitPreviewCollapsed = false; }
	function requestLongformStrategy(plan: GeneratePlanResponse): Promise<LongformStrategy | null> { prepareLongformPlan(plan); if (!plan.requires_user_confirmation) return Promise.resolve('single'); $store.pendingLongformPlan = plan; $store.longformStrategy = plan.recommended_action === 'split_generate' ? 'split_only' : 'split_merge'; $store.longformVerifyEnabled = plan.recommended_action.includes('verify'); $store.longformMergeEnabled = $store.longformStrategy === 'split_merge'; $store.longformMaxRetries = 2; $store.showLongformDialog = true; return new Promise<LongformStrategy | null>(r => { $store.pendingLongformResolve = r; }); }
	function closeLongformDialog(v: LongformStrategy | null) { const r = $store.pendingLongformResolve; $store.showLongformDialog = false; $store.pendingLongformResolve = null; $store.pendingLongformPlan = null; r?.(v); }
	function longformSegmentsFor(plan: GeneratePlanResponse): PlannedTextSegment[] { return plan.segments.length ? plan.segments : [{ index: 1, text: $store.text.trim(), char_count: $store.text.trim().length, segment_reason: 'direct_text' }]; }
	async function generate() { if (!$store.text.trim()) return; $store.error = ''; $store.busy = true; try { if ((isF5 || isCosyVoiceZeroShot) && !$store.voiceId) { $store.error = `${selected?.manifest.display_name ?? '当前模型'} 需要选择带参考音频和参考台词的本地音色。`; return; } if ((isF5 || isCosyVoiceZeroShot) && !selectedVoice?.reference_text.trim()) { $store.error = `${selectedVoice?.name ?? '当前音色'} 缺少参考台词。`; return; } if (isMimoClone && !selectedVoicePreviewUrl) { $store.error = '请选择一个带参考音频的本地音色。'; return; } const plan = await Api.generatePlan({ text: $store.text.trim(), engine_id: $store.engineId, planner_mode: 'auto', target_format: $store.outputFormat }); const lfChoice = await requestLongformStrategy(plan); if (!lfChoice) return; if (isMimoClone && $store.settings?.mimo_voiceclone_confirm_upload && !window.confirm(`MiMo 音色复刻会把「${selectedVoice?.name ?? '当前参考音色'}」发送到小米云端。继续吗？`)) return; const eng = $store.engines.find(i => i.manifest.engine_id === $store.engineId); if (eng && eng.state.status !== 'loaded') await Api.startEngine($store.engineId); if (lfChoice !== 'single') { const res = await Api.generateLongform({ generate_request: store.toRequest(), segments: longformSegmentsFor(plan), verify_enabled: $store.longformVerifyEnabled, merge_enabled: lfChoice === 'split_merge' && $store.longformMergeEnabled, max_retries: $store.longformMaxRetries, stop_merge_on_verification_failed: true, asr_engine_id: 'qwen3-asr-mlx', silence_ms: 300, normalize: false }); $store.longformTasks = [res, ...$store.longformTasks.filter(i => i.longform_task_id !== res.longform_task_id)]; $store.currentPage = 1; return; } const res = await Api.generate(store.toRequest()); $store.currentPage = 1; await poll(res.task_id); } catch (e) { $store.error = (e as Error).message; } finally { $store.busy = false; } }
	function reuse(t: GenerationTask) { store.fromRequest(t.parameters as unknown as GenerateRequest); }
	async function runTextTool(mode: 'clean' | 'numbers' | 'split') { if (!$store.text.trim() && mode !== 'split') return; $store.textToolBusy = mode; try { if (mode === 'clean') { $store.text = (await Api.cleanText($store.text)).text; return; } if (mode === 'numbers') { $store.text = (await Api.normalizeNumbers($store.text)).text; return; } $store.textSegments = (await Api.splitText($store.text)).segments; $store.showSplitPreview = true; $store.splitPreviewCollapsed = false; } finally { $store.textToolBusy = ''; } }
	async function cancelTask(t: GenerationTask) { $store.actionBusyTaskId = t.task_id; try { await Api.cancelTask(t.task_id); await refreshPageData(); } finally { $store.actionBusyTaskId = ''; } }
	async function retryTask(t: GenerationTask) { $store.actionBusyTaskId = t.task_id; try { const res = await Api.retryTask(t.task_id); $store.currentPage = 1; await poll(res.task_id); await refreshPageData(); } finally { $store.actionBusyTaskId = ''; } }
	async function deleteTaskRecord(t: GenerationTask) { if (!window.confirm(t.result_id ? '删除这条记录和本地音频？' : '删除这条任务记录？')) return; $store.actionBusyTaskId = t.task_id; try { await Api.deleteTask(t.task_id); $store.selectedTaskIds = $store.selectedTaskIds.filter(id => id !== t.task_id); await refreshPageData(); } finally { $store.actionBusyTaskId = ''; } }
	async function retryLongformTask(t: LongformTask) { $store.actionBusyTaskId = t.longform_task_id; try { const n = await Api.retryLongformFailed(t.longform_task_id); $store.longformTasks = [n, ...$store.longformTasks.filter(i => i.longform_task_id !== n.longform_task_id)]; } finally { $store.actionBusyTaskId = ''; } }
	function taskVerificationPending(t: GenerationTask) { if (t.status !== 'success' || !t.result_id || taskVerificationReport(t) || taskVerificationError(t)) return false; const c = new Date(t.completed_at ?? t.created_at).getTime(); if (!Number.isFinite(c)) return false; return Date.now() - c < 20 * 60 * 1000; }
	function taskVerificationReport(t: GenerationTask) { return $store.verificationReports[t.task_id] ?? t.verification; }
	function taskVerificationError(t: GenerationTask) { return $store.verificationErrors[t.task_id] || t.verification_error || ''; }
	async function verifyTask(t: GenerationTask) { if (!t.result_id) return; $store.verificationBusyTaskId = t.task_id; $store.verificationErrors = { ...$store.verificationErrors, [t.task_id]: '' }; try { const report = await Api.verifyTTSOutput({ result_id: t.result_id, expected_text: t.input_text, asr_engine_id: 'qwen3-asr-mlx', language: (t.parameters['language'] === 'en' || t.parameters['language'] === 'auto' ? t.parameters['language'] : 'zh') as 'auto' | 'zh' | 'en' }); $store.verificationReports = { ...$store.verificationReports, [t.task_id]: report }; $store.tasks = $store.tasks.map(i => i.task_id === t.task_id ? { ...i, verification: report, verification_error: null } : i); } catch (e) { $store.verificationErrors = { ...$store.verificationErrors, [t.task_id]: (e as Error).message || '校对失败' }; } finally { $store.verificationBusyTaskId = ''; } }
	function resultAudioUrl(t: GenerationTask) { return t.result_id ? `/api/history/${t.result_id}/audio` : ''; }
	function toggleResultPlayback(t: GenerationTask) { const url = resultAudioUrl(t); const audio = $store.resultPreviewAudio; if (!url || !audio) return; if ($store.resultAudioPlaying && $store.playingResultTaskId === t.task_id) { $store.resultAudioPlaying = false; audio.pause(); audio.currentTime = 0; return; } const abs = new URL(url, window.location.href).href; if (audio.src !== abs) audio.src = url; audio.currentTime = 0; $store.playingResultTaskId = t.task_id; $store.resultAudioPlaying = true; void audio.play().catch((e) => { $store.playingResultTaskId = ''; $store.resultAudioPlaying = false; $store.error = (e as Error).message; }); }
	function toggleTaskSelection(tId: string, c: boolean) { $store.selectedTaskIds = c ? [...$store.selectedTaskIds, tId] : $store.selectedTaskIds.filter(i => i !== tId); }
	function toggleVisibleSelection() { if (allVisibleSelected) { $store.selectedTaskIds = $store.selectedTaskIds.filter(id => !visibleSelectableTasks.some(t => t.task_id === id)); } else { $store.selectedTaskIds = Array.from(new Set([...$store.selectedTaskIds, ...visibleSelectableTasks.map(t => t.task_id)])); } }
	async function deleteSelectedTasks() { if (!$store.selectedTaskIds.length) return; if (!window.confirm(`批量删除 ${$store.selectedTaskIds.length} 条记录和本地音频？`)) return; await Promise.all($store.selectedTaskIds.map(id => Api.deleteTask(id))); $store.selectedTaskIds = []; await refreshPageData(); }
	function clearTaskFilters() { $store.taskQuery = ''; $store.taskStatusTab = 'all'; $store.taskEngineFilter = 'all'; $store.taskSourceFilter = 'all'; $store.taskDateFilter = 'all'; $store.taskSortBy = 'latest'; $store.currentPage = 1; }
	function taskPageJump(d: number) { $store.currentPage = Math.min(pageCount, Math.max(1, $store.currentPage + d)); }
	function taskPageGoTo(p: number) { $store.currentPage = Math.min(pageCount, Math.max(1, p)); }
	function jumpToPage() { const n = parseInt($store.pageJumpInput, 10); if (Number.isFinite(n) && n >= 1 && n <= pageCount) $store.currentPage = n; $store.pageJumpInput = ''; }
	function recalcAutoPageSize() { if (!$store.pageSizeAuto || !$store.resultGridEl) return; const fc = $store.resultGridEl.querySelector('.result-card') as HTMLElement | null; const cH = fc ? fc.offsetHeight + 12 : 260; const cols = Math.max(1, Math.floor($store.resultGridEl.getBoundingClientRect().width / 260)); const rows = Math.max(1, Math.floor((window.innerHeight - 200 - 60) / cH)); let ideal = Math.max(cols, rows * cols); if (ideal !== $store.pageSize) { $store.pageSize = ideal; if ($store.currentPage > Math.max(1, Math.ceil(filteredTasks.length / $store.pageSize))) $store.currentPage = 1; } }
	function checkOverflow(node: HTMLElement, _text: string) { let frame = 0; const check = () => { frame = 0; node.classList.toggle('fade-overflow', node.scrollHeight > node.offsetHeight); }; const schedule = () => { if (frame) cancelAnimationFrame(frame); frame = requestAnimationFrame(check); }; schedule(); return { update(_nextText: string) { schedule(); }, destroy() { if (frame) cancelAnimationFrame(frame); } }; }

	onMount(() => {
		async function initLoad() {
			for (let i = 0; i < 10; i++) {
				try {
					await refreshPageData();
					return;
				} catch {
					await new Promise(r => setTimeout(r, 2000));
				}
			}
		}
		initLoad();
		const id = setInterval(() => {
			if (hasRunningTasks || !$store.initialized) refreshPageData();
		}, 2000);
		const slowId = setInterval(() => {
			if (!hasRunningTasks && $store.initialized) refreshPageData();
		}, 15000);
		const or = () => recalcAutoPageSize();
		window.addEventListener('resize', or);
		_autoResizeRO = new ResizeObserver(or);
		return () => {
			clearInterval(id);
			clearInterval(slowId);
			window.removeEventListener('resize', or);
			_autoResizeRO?.disconnect();
		};
	});
	$effect(() => { if ($store.engineId !== $store.lastEngineId) store.setEngine($store.engineId); });
	$effect(() => { const eid = $store.engineId; const q = $store.speakerQuery.trim(); const g = $store.speakerGenderFilter; setTimeout(() => loadSpeakerCatalog(eid, q, g), 0); });
	$effect(() => { if (!$store.initialized) return; if (!usesReferenceVoice) { untrack(() => { $store.voiceId = ''; }); return; } if ($store.voiceId && !$store.voices.some(v => v.voice_id === $store.voiceId)) untrack(() => { $store.voiceId = ''; }); });
	$effect(() => { if ($store.currentPage > pageCount) $store.currentPage = pageCount; });
	$effect(() => { if ($store.pageSizeAuto && $store.resultGridEl) recalcAutoPageSize(); });
	$effect(() => { if (_autoResizeRO) _autoResizeRO.disconnect(); if ($store.resultGridEl && _autoResizeRO) _autoResizeRO.observe($store.resultGridEl); });
</script>

<svelte:head><title>语音合成 - 声音工作台</title></svelte:head>
<main class="page generate-page">
	<div class="page-head"><div><h1>语音合成</h1><p class="muted">短文本合成、文本处理、任务进度和生成记录统一放在一个工作台里。</p></div></div>
	<div class="workbench"><div class="panel stack compose-panel">
		<div class="row gen-section-head"><div><h2>合成预设</h2><p class="muted">跟随当前引擎，只显示可用于 {selected?.manifest.display_name ?? $store.engineId} 的参数组合。</p></div><div class="row wrap preset-tools"><span class="muted">{enginePresets.length} 组</span><button class="btn compact" type="button" onclick={() => openPresetEditor()}><Plus size={14} /> 保存当前</button></div></div>
		{#if enginePresets.length}<div class="preset-strip">{#each enginePresets as p}<div class="preset-chip"><button class="preset-main" type="button" onclick={() => applyPreset(p)}><strong>{p.name}</strong><span>{p.scene || p.description || H.engineTypeLabel(p.engine_id, engineMap)}</span></button><button type="button" class="text-pop preset-info" aria-label="查看预设说明" data-text={`${p.description || '无'}\n示例：${p.sample_text || '未设置'}\n标签：${p.tags.join('、') || '无'}`}><Info size={13} /></button>{#if p.preset_id.startsWith('custom_')}<button class="gen-icon-btn mini" type="button" aria-label="编辑预设" data-tooltip="编辑这个自定义预设" onclick={() => openPresetEditor(p)}><Pencil size={13} /></button><button class="gen-icon-btn mini danger" type="button" aria-label="删除预设" data-tooltip="删除这个自定义预设" onclick={() => deletePreset(p)}><Trash2 size={13} /></button>{/if}</div>{/each}</div>{:else}<p class="muted gen-empty-line">当前引擎还没有预设。</p>{/if}
		{#if $store.showPresetEditor}<div class="preset-editor"><div class="row gen-section-head"><div><h3>{$store.editingPresetId ? '编辑自定义预设' : '保存当前为预设'}</h3><p class="muted">绑定引擎：{selected?.manifest.display_name ?? $store.engineId}</p></div><button class="gen-icon-btn mini" type="button" aria-label="关闭预设编辑器" data-tooltip="关闭预设编辑器" onclick={() => ($store.showPresetEditor = false)}>X</button></div><div class="preset-editor-grid"><label class="field"><span>名称</span><input bind:value={$store.presetDraft.name} placeholder="例如：课程慢讲" /></label><label class="field"><span>场景</span><input bind:value={$store.presetDraft.scene} placeholder="例如：教程 / 长文旁白" /></label><label class="field wide"><span>描述</span><input bind:value={$store.presetDraft.description} placeholder="简短说明" /></label><label class="field"><span>标签</span><input bind:value={$store.presetDraft.tags} placeholder="慢讲，课程" /></label><label class="field wide"><span>示例文本</span><textarea bind:value={$store.presetDraft.sample_text} placeholder="可选"></textarea></label></div><div class="row wrap"><button class="btn primary compact" type="button" onclick={savePreset} disabled={$store.presetBusy || !$store.presetDraft.name.trim()}><Save size={14} /> {$store.presetBusy ? '保存中' : '保存预设'}</button><button class="btn compact" type="button" onclick={() => ($store.showPresetEditor = false)}>取消</button></div></div>{/if}
		<div class="param-inline-row">
			<label class="param-inline"><span>引擎</span><EngineSelector engines={ttsEngines} bind:value={$store.engineId} /></label>
			{#if usesReferenceVoice}<label class="param-inline"><span>声音</span><div class="voice-inline"><VoiceSelector voices={$store.voices} bind:value={$store.voiceId} /><button class="gen-icon-btn mini" type="button" aria-label={$store.voicePreviewPlaying ? '暂停试听音色' : '试听当前音色'} data-tooltip={$store.voicePreviewPlaying ? '暂停当前音色试听' : '试听当前选择的音色'} onclick={previewSelectedVoice} disabled={!selectedVoicePreviewUrl}>{#if $store.voicePreviewPlaying}<Pause size={13} />{:else}<Play size={13} />{/if}</button></div></label>{#if selectedVoicePreviewUrl}<audio bind:this={$store.voicePreviewAudio} src={selectedVoicePreviewUrl} preload="metadata" onended={() => ($store.voicePreviewPlaying = false)}></audio>{/if}{/if}
			{#if activeParamKeys.has('speed')}<label class="param-inline-range"><span>语速 {$store.speed.toFixed(1)}x</span><input type="range" min="0.5" max="2" step="0.1" bind:value={$store.speed} /></label>{/if}
			<label class="param-inline"><span>格式</span><select bind:value={$store.outputFormat}><option value="wav">WAV</option><option value="mp3">MP3</option><option value="flac">FLAC</option></select></label>
			<button class="btn" type="button" onclick={() => ($store.showMoreParams = !$store.showMoreParams)}><Settings size={14} /> {$store.showMoreParams ? '收起' : '更多'}</button>
		</div>
		<TextInput bind:text={$store.text} engineId={$store.engineId} ontexttool={(mode: 'clean' | 'numbers') => runTextTool(mode)} textToolBusy={$store.textToolBusy} />
		{#if $store.showMoreParams}<div class="more-params-panel">
			{#if isEmotiVoice}<div class="engine-note span-full"><strong>EmotiVoice</strong><small>使用官方说话人和情绪提示。</small></div>{:else if isF5}<div class="engine-note span-full"><strong>F5-TTS</strong><small>需要本地参考音频和准确参考台词。</small></div>{:else if isCosyVoice}<div class="engine-note span-full"><strong>CosyVoice SFT</strong><small>使用官方 SFT 预置音色。</small></div>{:else if isCosyVoiceZeroShot}<div class="engine-note span-full"><strong>CosyVoice Zero-Shot</strong><small>需要本地参考音频和准确参考台词。</small></div>{/if}
			{#if activeParamKeys.has('speaker_id')}<div class="field param-field span-full"><label class="param-label" for="spk">音色</label><div class="param-control">{#if isEmotiVoice}<div class="speaker-catalog-tools"><div class="gen-search-field speaker-search"><Search size={14} /><input bind:value={$store.speakerQuery} placeholder="搜索" />{#if $store.speakerQuery.trim()}<button class="gen-search-clear" type="button" onclick={() => ($store.speakerQuery = '')}><X size={13} /></button>{/if}</div><select class="speaker-gender" bind:value={$store.speakerGenderFilter}><option value="all">全部</option><option value="F">女声</option><option value="M">男声</option></select></div>{/if}<select id="spk" bind:value={$store.speakerId}>{#each speakerChoices as o}<option value={o.value}>{o.label}</option>{/each}</select>{#if isEmotiVoice}<small>{$store.speakerCatalogLoading ? '读取中' : `结果 ${$store.speakerCatalog.length} 条`}</small>{/if}</div></div>{/if}
			{#if activeParamKeys.has('prompt')}<div class="field param-field span-full"><label class="param-label" for="vprompt">情绪提示</label><div class="param-control"><select id="vprompt" bind:value={$store.voicePrompt}>{#each promptOptions as o}<option value={o.value}>{o.label}</option>{/each}</select></div></div>{/if}
			{#if isMimoPreset}<div class="field param-field span-full"><label class="param-label" for="mimo-v">MiMo 音色</label><div class="param-control"><select id="mimo-v" bind:value={$store.mimoVoice}>{#each mimoVoiceOptions as o}<option value={o.value}>{o.label}</option>{/each}</select></div></div>{/if}
			{#if activeParamKeys.has('language')}<div class="field param-field"><label class="param-label" for="lang">语言</label><div class="param-control"><select id="lang" bind:value={$store.language}><option value="zh">中文</option><option value="en">英文</option><option value="auto">自动</option></select></div></div>{/if}
			{#if isMimo}{#if isMimoDesign}<div class="field param-field span-full"><label class="param-label" for="vd-prompt">音色描述</label><div class="param-control"><textarea id="vd-prompt" bind:value={$store.voiceDesignPrompt}></textarea><small>描述声音本身：年龄、性别、质感、语速和情绪底色。</small></div></div>{:else}<div class="field param-field span-full"><label class="param-label" for="style">风格指令</label><div class="param-control"><textarea id="style" bind:value={$store.styleInstruction} placeholder="例如：语速稍慢，语气温柔，像知识视频旁白。"></textarea></div></div>{/if}{/if}
			{#if supportsEmotion}<div class="field param-field"><label class="param-label" for="emo">情绪</label><div class="param-control"><select id="emo" bind:value={$store.emotion}><option value="">跟随参考音色</option><option value="calm">自然</option><option value="happy">高兴</option><option value="sad">悲伤</option><option value="angry">愤怒</option><option value="afraid">恐惧</option><option value="disgusted">反感</option><option value="melancholic">低落</option><option value="surprised">惊讶</option></select></div></div>{#if isIndexTTS && !followsReferenceEmotion}<div class="field param-slider"><div class="field-head"><label for="emo-a">情绪强度</label><input class="field-number" type="number" min="0" max="1" step="0.05" bind:value={$store.emoAlpha} /></div><div class="range-control"><input id="emo-a" type="range" min="0" max="1" step="0.05" bind:value={$store.emoAlpha} /><div class="range-scale"><span>0</span><span>1</span></div></div></div>{/if}{/if}
			{#if isOmniVoice && !$store.voiceId}<div class="field param-field"><label class="param-label" for="vd">设计标签</label><div class="param-control"><select id="vd" bind:value={$store.voiceDesign}><option value="女，青年，中音调">女，青年，中音调</option><option value="男，青年，中音调">男，青年，中音调</option><option value="女，中年，高音调">女，中年，高音调</option><option value="男，中年，低音调">男，中年，低音调</option><option value="女，青年，耳语">女，青年，耳语</option></select></div></div>{/if}
			{#if selected}<ParameterPanel parameterSchema={selected.manifest.parameter_schema.filter(p => p.level === 'advanced' || p.level === 'developer')} values={{ temperature: $store.temperature, top_p: $store.topP, top_k: $store.topK, max_text_tokens_per_segment: $store.maxTextTokensPerSegment, interval_silence: $store.intervalSilence, diffusion_steps: $store.diffusionSteps, cfg_rate: $store.cfgRate, nfe_step: $store.nfeStep, cfg_strength: $store.cfgStrength, target_rms: $store.targetRms, cross_fade_duration: $store.crossFadeDuration, remove_silence: $store.removeSilence, optimize_text_preview: $store.optimizeTextPreview }} onChange={(k, v) => { const st: Record<string, (x: unknown) => void> = { temperature: (x: unknown) => $store.temperature = x as number, top_p: (x: unknown) => $store.topP = x as number, top_k: (x: unknown) => $store.topK = x as number, max_text_tokens_per_segment: (x: unknown) => $store.maxTextTokensPerSegment = x as number, interval_silence: (x: unknown) => $store.intervalSilence = x as number, diffusion_steps: (x: unknown) => $store.diffusionSteps = x as number, cfg_rate: (x: unknown) => $store.cfgRate = x as number, nfe_step: (x: unknown) => $store.nfeStep = x as number, cfg_strength: (x: unknown) => $store.cfgStrength = x as number, target_rms: (x: unknown) => $store.targetRms = x as number, cross_fade_duration: (x: unknown) => $store.crossFadeDuration = x as number, remove_silence: (x: unknown) => $store.removeSilence = x as boolean, optimize_text_preview: (x: unknown) => $store.optimizeTextPreview = x as boolean }; st[k]?.(v); }} />{/if}
		</div>{/if}
		<div class="row tool-row"><div class="row wrap tool-actions"><span class="muted">{$store.text.length} 字</span><button class="btn tool-btn text-pop" data-text="清理多余空白、异常标点" onclick={() => runTextTool('clean')} disabled={$store.textToolBusy !== ''}><Wand2 size={15} /> {$store.textToolBusy === 'clean' ? '清洗中' : '清洗文本'}</button><button class="btn tool-btn text-pop" data-text="数字、年份转口播写法" onclick={() => runTextTool('numbers')} disabled={$store.textToolBusy !== ''}><Hash size={15} /> {$store.textToolBusy === 'numbers' ? '处理中' : '数字规范'}</button><button class="btn tool-btn text-pop" data-text="按语义预览切句和停顿" onclick={() => runTextTool('split')} disabled={!$store.text.trim() || $store.textToolBusy !== ''}><Scissors size={15} /> {$store.textToolBusy === 'split' ? '分句中' : '分句预览'}</button></div><button class="btn primary tool-btn text-pop" disabled={$store.busy || !$store.text.trim()} onclick={generate}><Send size={15} /> {$store.busy ? '生成中' : '生成'}</button></div>
		{#if $store.error}<div class="badge fail">{$store.error}</div>{/if}
		<audio class="result-shared-audio" bind:this={$store.resultPreviewAudio} preload="none" onended={() => { $store.playingResultTaskId = ''; $store.resultAudioPlaying = false; }}></audio>
		{#if $store.showLongformDialog && $store.pendingLongformPlan}<div class="gen-modal-backdrop"><div class="longform-dialog" role="dialog" aria-modal="true"><div class="dialog-head"><div><h3>长文本生成策略</h3><p class="muted">预计 {$store.pendingLongformPlan.segments.length} 段。{$store.pendingLongformPlan.planner_reason}</p></div><button class="gen-icon-btn" type="button" aria-label="关闭长文本策略弹窗" data-tooltip="关闭长文本策略弹窗" onclick={() => closeLongformDialog(null)}>×</button></div>{#if $store.pendingLongformPlan.warnings.length}<p class="dialog-warning">{$store.pendingLongformPlan.warnings[0]}</p>{/if}<div class="strategy-grid"><button class:active={$store.longformStrategy === 'split_merge'} type="button" onclick={() => { $store.longformStrategy = 'split_merge'; $store.longformMergeEnabled = true; $store.longformVerifyEnabled = true; }}><strong>分段生成并合并</strong><span>逐段生成，校对后自动合并。</span></button><button class:active={$store.longformStrategy === 'split_only'} type="button" onclick={() => { $store.longformStrategy = 'split_only'; $store.longformMergeEnabled = false; }}><strong>只分段生成</strong><span>保留每段结果，先人工复听。</span></button><button class:active={$store.longformStrategy === 'single'} type="button" onclick={() => { $store.longformStrategy = 'single'; $store.longformMergeEnabled = false; }}><strong>仍然单条生成</strong><span>最快开始，但容易超时或截断。</span></button></div><div class="dialog-options"><label class="check-row"><input type="checkbox" bind:checked={$store.longformVerifyEnabled} disabled={$store.longformStrategy === 'single'} /><span>生成后自动 ASR 校对</span></label><label class="field compact-field"><span>失败重试</span><input type="number" min="0" max="5" bind:value={$store.longformMaxRetries} disabled={$store.longformStrategy === 'single'} /></label></div><div class="dialog-preview">{#each $store.pendingLongformPlan.segments.slice(0, 4) as seg}<p><strong>{seg.index}</strong> {seg.text}</p>{/each}{#if $store.pendingLongformPlan.segments.length > 4}<p class="muted">还有 {$store.pendingLongformPlan.segments.length - 4} 段...</p>{/if}</div><div class="dialog-actions"><button class="btn" type="button" onclick={() => closeLongformDialog(null)}>取消</button><button class="btn primary" type="button" onclick={() => closeLongformDialog($store.longformStrategy)}>确认</button></div></div></div>{/if}
		{#if $store.showSplitPreview && $store.textSegments.length}<div class="split-preview" class:collapsed={$store.splitPreviewCollapsed}><div class="split-preview-head"><div class="split-preview-title"><div class="row wrap split-title-row"><h3>{$store.lastGeneratePlan ? '系统分段计划' : '智能分句预览'}</h3><span class="badge">{$store.textSegments.length} 段</span></div><p>用来提前检查停顿和节奏。{#if $store.lastGeneratePlan}{$store.lastGeneratePlan.planner_reason}{/if}</p></div><button class="gen-icon-btn split-collapse" class:expanded={!$store.splitPreviewCollapsed} type="button" aria-label={$store.splitPreviewCollapsed ? '展开分句预览' : '收起分句预览'} data-tooltip={$store.splitPreviewCollapsed ? '展开分句预览' : '收起分句预览'} onclick={() => ($store.splitPreviewCollapsed = !$store.splitPreviewCollapsed)}><ChevronRight size={15} /></button></div>{#if !$store.splitPreviewCollapsed}<div class="segment-list">{#each $store.textSegments as seg, i}<div class="segment-card"><span class="segment-index">{i + 1}</span><p>{seg}</p></div>{/each}</div>{/if}</div>{/if}
		<div class="result-panel stack section-divider" id="records">
			<div class="row gen-section-head result-headline"><h2>结果与记录</h2><div class="records-row-summary"><span class="muted">{filteredTasks.length} 条</span>{#if statusCounts.active}<span class="badge">生成中 {queueCounts.processing}</span><span class="badge">等待 {queueCounts.waiting}</span>{/if}{#if $store.selectedTaskIds.length}<span class="badge ok">已选 {$store.selectedTaskIds.length}</span>{/if}</div></div>
			<div class="records-toolbar">
				<div class="toolbar-tabs">
					<div class="gen-segmented compact-tabs" role="tablist">
						<button class:active={$store.taskStatusTab === 'all'} type="button" onclick={() => { $store.taskStatusTab = 'all'; $store.currentPage = 1; }}>全部<span>{statusCounts.all}</span></button>
						<button class:active={$store.taskStatusTab === 'active'} type="button" onclick={() => { $store.taskStatusTab = 'active'; $store.currentPage = 1; }}>队列<span>{statusCounts.active}</span></button>
						<button class:active={$store.taskStatusTab === 'success'} type="button" onclick={() => { $store.taskStatusTab = 'success'; $store.currentPage = 1; }}>成功<span>{statusCounts.success}</span></button>
						<button class:active={$store.taskStatusTab === 'failed'} type="button" onclick={() => { $store.taskStatusTab = 'failed'; $store.currentPage = 1; }}>异常<span>{statusCounts.failed}</span></button>
					</div>
				</div>
				<div class="toolbar-control-row">
					<div class="records-filter-inline">
						<div class="gen-search-field compact"><Search size={13} /><input bind:value={$store.taskQuery} placeholder="搜索台词、模型、音色、状态" /></div>
						<select class="compact-filter" bind:value={$store.taskEngineFilter}>{#each taskEngineOptions as o}<option value={o}>{o === 'all' ? '全部模型' : o}</option>{/each}</select>
						<select class="compact-filter" bind:value={$store.taskSourceFilter}><option value="all">全部来源</option><option value="local">本地</option><option value="cloud">云端</option></select>
						<select class="compact-filter" bind:value={$store.taskDateFilter}><option value="all">全部时间</option><option value="today">今天</option><option value="7d">最近 7 天</option><option value="30d">最近 30 天</option></select>
						<select class="compact-filter" bind:value={$store.taskSortBy}><option value="latest">最新</option><option value="oldest">最旧</option><option value="duration_desc">时长↓</option></select>
					</div>
					<div class="toolbar-right">
						{#if pageCount > 1}
							<div class="pagination-bar pagination-bar-top">
								<button class="btn icon-text-btn" aria-label="跳到首页" data-tooltip="跳到第一页" onclick={() => taskPageGoTo(1)} disabled={$store.currentPage <= 1}><ChevronsLeft size={15} /></button>
								<button class="btn icon-text-btn" aria-label="上一页" data-tooltip="查看上一页记录" onclick={() => taskPageJump(-1)} disabled={$store.currentPage <= 1}><ChevronLeft size={15} /></button>
								<span class="muted page-info">{$store.currentPage} / {pageCount}</span>
								<button class="btn icon-text-btn" aria-label="下一页" data-tooltip="查看下一页记录" onclick={() => taskPageJump(1)} disabled={$store.currentPage >= pageCount}><ChevronRight size={15} /></button>
								<button class="btn icon-text-btn" aria-label="跳到尾页" data-tooltip="跳到最后一页" onclick={() => taskPageGoTo(pageCount)} disabled={$store.currentPage >= pageCount}><ChevronsRight size={15} /></button>
							</div>
						{/if}
						<div class="toolbar-actions">
							<button class="gen-icon-btn" type="button" aria-label={allVisibleSelected ? '取消选择当前页' : '选择当前页'} data-tooltip={allVisibleSelected ? '取消选择当前页可删除的记录' : '选择当前页可删除的记录'} onclick={toggleVisibleSelection} disabled={!visibleSelectableTasks.length}>{#if allVisibleSelected}<CheckSquare size={15} />{:else}<Square size={15} />{/if}</button>
							<button class="gen-icon-btn danger" type="button" aria-label="删除已选记录" data-tooltip="删除当前已选中的任务记录" onclick={deleteSelectedTasks} disabled={!$store.selectedTaskIds.length}><Trash2 size={15} /></button>
							{#if hasActiveFilters}<button class="gen-icon-btn" type="button" aria-label="清除筛选" data-tooltip="清除搜索、模型、来源和时间筛选" onclick={clearTaskFilters}><X size={15} /></button>{/if}
							<button class="gen-icon-btn" type="button" aria-label="刷新列表" data-tooltip="重新加载任务记录和队列状态" onclick={refreshPageData} disabled={$store.busy}><RotateCcw size={15} /></button>
						</div>
					</div>
				</div>
			</div>
			{#if H.queueSummaryText(queueCounts, queueOrderedTasks, engineMap)}<div class="queue-insight"><Info size={14} /><span>{H.queueSummaryText(queueCounts, queueOrderedTasks, engineMap)}</span></div>{/if}
			{#if visibleLongformTasks.length}<section class="longform-list"><div class="row section-subhead"><div><h3>长文本任务</h3><p class="muted">进行中的分段生成、校对、重试和合并父任务。</p></div></div>{#each visibleLongformTasks.slice(0, 6) as t}<article class={`longform-card ${t.status}`}><div class="longform-card-head"><div><strong>{H.longformTitle(t)}</strong><p class="muted">{H.longformStatusText(t)}</p></div><div class="row wrap longform-actions"><span class="badge">{Math.round(t.progress * 100)}%</span>{#if t.export_id}<a class="btn" href={H.longformDownloadUrl(t)}>下载合并音频</a>{/if}{#if t.status === 'failed'}<button class="btn" type="button" onclick={() => retryLongformTask(t)} disabled={$store.actionBusyTaskId === t.longform_task_id}><RotateCcw size={15} /> 重试失败段</button>{/if}</div></div><div class="progress-track"><div class="progress-fill" style={`width:${Math.max(3, Math.round(t.progress * 100))}%`}></div></div><div class="longform-segments">{#each t.segments as seg}<div class={`longform-segment ${seg.status}`}><span class="badge">{seg.index}</span><p>{seg.text}</p><span class="badge">{taskStatusLabel(seg.status)}</span>{#if seg.verification}<span class={`badge verify-${seg.verification.status}`}>{H.verificationStatusLabel(seg.verification.status)}</span>{/if}{#if seg.error_message}<span class="muted">{seg.error_message}</span>{/if}</div>{/each}</div>{#if t.error_message}<p class="muted error-line task-error-scroll" use:checkOverflow={t.error_message}>{t.error_message}</p>{/if}</article>{/each}</section>{/if}
			{#if pagedTasks.length}<div class="result-grid" bind:this={$store.resultGridEl}>{#each pagedTasks as t}<article class={`card stack result-card engine-surface ${H.engineKind(t.engine_id, engineMap) === 'cloud' ? 'engine-cloud' : 'engine-local'}${$store.resultAudioPlaying && $store.playingResultTaskId === t.task_id ? ' playing' : ''}`}><div class="result-head"><div class="title-row"><input type="checkbox" checked={$store.selectedTaskIds.includes(t.task_id)} disabled={!H.taskCanDelete(t)} onchange={(e) => toggleTaskSelection(t.task_id, (e.currentTarget as HTMLInputElement).checked)} /><strong class="result-title" title={H.displayTitle(t)}>{H.displayTitle(t)}</strong></div><span class="badge result-status" class:ok={t.status === 'success'} class:fail={t.status === 'failed'} class:warn={t.status === 'cancelled' || H.taskIsActive(t)}>{H.taskStatusPillLabel(t, queueCounts, queueOrderedTasks)}</span></div><div class="result-meta result-meta-primary"><span class="badge"><Mic size={11} /> {H.voiceBadgeLabel(t, voiceMap)}</span><span class="badge text-pop result-script-chip" data-text={H.displayTitle(t)}><FileText size={13} /> 台词</span>{#if H.longformResultLabel(t)}<span class="badge longform-result-badge" class:merged={H.taskIsLongformExport(t)} title={H.longformResultTitle(t)}>{H.longformResultLabel(t)}</span>{/if}</div><div class="result-meta result-meta-secondary"><span class="badge engine"><Cpu size={11} /> {engineMap.get(t.engine_id)?.manifest.display_name ?? t.engine_id}</span><span class="badge badge-kind">{H.engineTypeLabel(t.engine_id, engineMap)}</span>{#if t.created_at}<span class="badge">{H.formatTime(t.created_at)}</span>{/if}</div><div class="row result-info"><p class="muted result-subline">{H.taskTimingLine(t)}</p><div class="row wrap result-info-right">{#if t.result_duration_ms}<span class="badge">{H.formatAudioDuration(t.result_duration_ms)}</span>{/if}{#if H.taskIsActive(t)}<button class="gen-icon-btn danger" aria-label="取消任务" data-tooltip="取消这个正在排队或生成中的任务" onclick={() => cancelTask(t)} disabled={$store.actionBusyTaskId === t.task_id}><X size={14} /></button>{/if}<button type="button" class="param-pop compact" aria-label="查看生成参数" data-tooltip="查看这条记录使用的生成参数"><SlidersHorizontal size={13} /><span class="param-panel" role="tooltip"><strong>生成参数</strong><span class="param-grid">{#each H.taskParameterEntries(t, engineMap, voiceMap) as e}<span class="param-key">{e.label}</span><span class="param-value">{e.value}</span>{/each}</span></span></button></div></div>{#if H.taskIsActive(t)}<div class="progress-block"><div class="row progress-head"><span class="muted">{H.taskStageLabel(t, queueOrderedTasks)}</span><span class="badge">{H.progressLabel(t, queueOrderedTasks)}</span></div><div class="progress-track" class:waiting-track={H.taskIsWaiting(t)}><div class="progress-fill" class:waiting-fill={H.taskIsWaiting(t)} style={`width:${H.taskProgressWidth(t)}%`}></div></div><div class="row wrap progress-foot"><span class="muted">{#if H.taskIsWaiting(t)}已等待 {H.formatSeconds(H.waitingSeconds(t))}{:else}已运行 {H.elapsedLabel(t)}{/if}</span>{#if H.taskEtaLabel(t)}<span class="muted">{H.taskEtaLabel(t)}</span>{/if}</div>{#if H.taskRuntimeHint(t, queueCounts, queueOrderedTasks)}<p class="progress-hint">{H.taskRuntimeHint(t, queueCounts, queueOrderedTasks)}</p>{/if}</div>{/if}{#if taskVerificationReport(t)}{@const r = taskVerificationReport(t)}<div class="verification-line {r.status}"><span class="dot"></span>{H.verificationStatusLabel(r.status)}<span class="coverage">覆盖率 {Math.round(r.coverage * 100)}%</span></div>{:else if taskVerificationPending(t)}<p class="muted verification-pending-line">自动校对中…</p>{:else if taskVerificationError(t)}<p class="muted error-line">{taskVerificationError(t)}</p>{/if}{#if t.error_message}<p class="muted error-line task-error-scroll" use:checkOverflow={t.error_message}>{t.error_message}</p>{/if}<div class="result-footer" class:without-audio={!t.result_id}>{#if t.result_id}<div class="result-audio-compact"><PlaybackControls task={t} isPlaying={$store.resultAudioPlaying && $store.playingResultTaskId === t.task_id} onPlay={() => toggleResultPlayback(t)} onStop={() => toggleResultPlayback(t)} /><span class="muted audio-compact-label">{t.result_duration_ms ? H.formatAudioDuration(t.result_duration_ms) : '播放结果'}</span><a class="gen-icon-btn result-download-btn" href={resultAudioUrl(t)} aria-label="下载音频" data-tooltip="下载这条记录生成的音频"><Download size={15} /></a></div>{/if}<div class="row wrap result-card-actions">{#if t.status === 'failed'}<button class="gen-icon-btn" aria-label="重试任务" data-tooltip="使用原参数重新尝试生成" onclick={() => retryTask(t)} disabled={$store.actionBusyTaskId === t.task_id}><RotateCcw size={15} /></button>{/if}{#if H.taskCanDelete(t)}<button class="gen-icon-btn" aria-label="复用参数" data-tooltip="把这条记录的文本和参数带回上方生成区" onclick={() => reuse(t)} disabled={$store.actionBusyTaskId === t.task_id}><Repeat size={15} /></button>{/if}{#if !H.taskIsActive(t)}<button class="gen-icon-btn danger" aria-label="删除记录" data-tooltip="删除这条任务记录" onclick={() => deleteTaskRecord(t)} disabled={$store.actionBusyTaskId === t.task_id}><Trash2 size={15} /></button>{/if}</div></div></article>{/each}</div>{#if pageCount > 1}<div class="pagination-bar"><button class="btn" onclick={() => $store.currentPage = 1} disabled={$store.currentPage <= 1}><ChevronsLeft size={15} /> 首页</button><button class="btn" onclick={() => taskPageJump(-1)} disabled={$store.currentPage <= 1}><ChevronLeft size={15} /> 上一页</button><span class="muted">第 {$store.currentPage} / {pageCount} 页</span><div class="page-jump"><span class="muted">跳至</span><input type="number" min="1" max={pageCount} bind:value={$store.pageJumpInput} onkeydown={(e) => e.key === 'Enter' && jumpToPage()} /><span class="muted">页</span></div><button class="btn" onclick={() => taskPageJump(1)} disabled={$store.currentPage >= pageCount}>下一页 <ChevronRight size={15} /></button><button class="btn" onclick={() => $store.currentPage = pageCount} disabled={$store.currentPage >= pageCount}>尾页 <ChevronsRight size={15} /></button></div>{/if}{:else}<div class="empty">当前筛选下没有任务记录。</div>{/if}
			</div>
		</div>
	</div>
</main>

<style>@import './+page.css';</style>
